  for(i=0;i<(g.lights||[]).length;i++){
    L=g.lights[i]; if(!L) continue;
    if(L.i0===undefined) L.i0=L.i;
    L.c=H2.lamps[Math.floor(fxr()*H2.lamps.length)];
    L.i=Math.min(H2.lampMax,Math.max(L.i0,L.i0*H2.lampI));
