  for(i=src.length-1;i>0;i--){ k=Math.floor(fxr()*(i+1)); tmp=src[i]; src[i]=src[k]; src[k]=tmp; }
  for(i=0;i<src.length&&list.length<H2.pumps;i++){
    for(j=0;j<6;j++){
      a=fxr()*6.2832; r=fxn(20,42); x=src[i].x+Math.cos(a)*r; y=src[i].y+Math.sin(a)*r;
